'use strict';
const CATEGORY_NAMES={'outboard':'아웃보드','deep-dive':'엔지니어 딥다이브','microphone':'마이크'};
let currentCategory=new URLSearchParams(location.search).get('category')||'';
if(!CATEGORY_NAMES[currentCategory])currentCategory='';
const search=document.getElementById('catalog-search');
const normalizeSearch=value=>String(value).toLocaleLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderCatalog(){const query=normalizeSearch(search.value.trim());const catalog=window.BLUEGEE_CATALOG||[];const results=catalog.filter(item=>(!currentCategory||item.category===currentCategory)&&(!query||normalizeSearch([item.id,item.title,item.kind,item.description,CATEGORY_NAMES[item.category]].join(' ')).includes(query)));document.getElementById('catalog-title').textContent=CATEGORY_NAMES[currentCategory]||'전체 가이드';document.getElementById('result-count').textContent=results.length+'편';document.getElementById('all-guides').hidden=!currentCategory;document.querySelectorAll('[data-category].category-link').forEach(link=>{const active=link.dataset.category===currentCategory;link.classList.toggle('selected',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.getElementById('guide-list').innerHTML=results.map(item=>`<article class="guide-entry" data-category="${item.category}"><span class="guide-number">${escapeHTML(item.id)}</span><div class="guide-info"><a class="guide-title" href="${escapeHTML(item.url)}">${escapeHTML(item.title)}</a><p class="guide-description">${escapeHTML(item.description)}</p><div class="guide-meta"><span class="kind-tag">${escapeHTML(item.kind)}</span><span>${escapeHTML(CATEGORY_NAMES[item.category])}</span><span>${item.chapters?.length||26}장</span></div></div><a class="read-link" href="${escapeHTML(item.url)}" aria-label="${escapeHTML(item.title)} 가이드 읽기">읽기</a></article>`).join('');document.getElementById('empty-state').hidden=results.length!==0;}
document.querySelector('.search-form').addEventListener('submit',event=>{event.preventDefault();renderCatalog();});search.addEventListener('input',renderCatalog);document.getElementById('reset-search').addEventListener('click',()=>{search.value='';renderCatalog();search.focus();});document.querySelectorAll('.category-link').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();currentCategory=currentCategory===link.dataset.category?'':link.dataset.category;history.pushState({},'',currentCategory?'?category='+currentCategory:location.pathname);renderCatalog();}));addEventListener('popstate',()=>{currentCategory=new URLSearchParams(location.search).get('category')||'';renderCatalog();});renderCatalog();
